-- SAIF / LSIF Dev v0.26A.1.22
-- Import deterministic 32-slot house/property canonical plan. Staging only.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP PROCEDURE IF EXISTS saif_import_property_plan_v026A122;
DELIMITER $$
CREATE PROCEDURE saif_import_property_plan_v026A122()
BEGIN
 DECLARE v_source BIGINT UNSIGNED DEFAULT NULL;
 SELECT id INTO v_source FROM offline_property_source_sessions WHERE parser_version='saif-property-source-parser-v0.26A.1.21' AND status='complete' ORDER BY id DESC LIMIT 1;
 IF v_source IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v0.26A.1.21 complete property source session not found'; END IF;
 SET @source_session_id=v_source;
 DELETE FROM offline_property_resolver_sessions WHERE source_session_id=v_source AND resolver_version='saif-house-property-resolver-v0.26A.1.22';
 SET @resolver_session_id=LAST_INSERT_ID();
 IF (SELECT COUNT(*) FROM offline_property_canonical_plan WHERE resolver_session_id=@resolver_session_id)<>32 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Canonical property plan count must be 32'; END IF;
 UPDATE offline_property_resolver_sessions SET status='complete',total_plans=32,baseline_ready_rows=29,deferred_rows=3,exact_pair_rows=30,unpaired_asset_rows=2,savepoint_linked_rows=30,garage_candidate_rows=13,completed_at=CURRENT_TIMESTAMP WHERE id=@resolver_session_id;
 SELECT id,resolver_version,status,total_plans,baseline_ready_rows,deferred_rows,exact_pair_rows,unpaired_asset_rows,savepoint_linked_rows,garage_candidate_rows FROM offline_property_resolver_sessions WHERE id=@resolver_session_id;
END$$
DELIMITER ;
CALL saif_import_property_plan_v026A122();
DROP PROCEDURE IF EXISTS saif_import_property_plan_v026A122;
